"Yes. Your tasks live in your account, not on one device. Add a task on your laptop during class and tick it off from your phone later, just log in with the same account. Changes made while you are offline are kept on your device and sync automatically when the connection returns.": "ಹೌದು. ನಿಮ್ಮ ಟಾಸ್ಕ್‌ಗಳು ಒಂದು ಸಾಧನದಲ್ಲಿ ಅಲ್ಲ, ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿರುತ್ತವೆ. ಕ್ಲಾಸ್ ಸಮಯದಲ್ಲಿ ಲ್ಯಾಪ್‌ಟಾಪ್‌ನಲ್ಲಿ ಟಾಸ್ಕ್ ಸೇರಿಸಿ, ನಂತರ ಫೋನ್‌ನಿಂದ ಟಿಕ್ ಮಾಡಿ; ಅದೇ ಖಾತೆಯಲ್ಲಿ ಲಾಗಿನ್ ಆದರೆ ಸಾಕು. ಆಫ್‌ಲೈನ್‌ನಲ್ಲಿ ಮಾಡಿದ ಬದಲಾವಣೆಗಳು ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ ಉಳಿದು, ಕನೆಕ್ಷನ್ ಬಂದಾಗ ತಾನಾಗಿ ಸಿಂಕ್ ಆಗುತ್ತವೆ.",
"How do I add a task?": "ಟಾಸ್ಕ್ ಹೇಗೆ ಸೇರಿಸುವುದು?",
