"Add the missing requirements listed below.": "ಕೆಳಗೆ ಪಟ್ಟಿ ಮಾಡಿರುವ ಬಾಕಿ ಅವಶ್ಯಕತೆಗಳನ್ನು ಸೇರಿಸಿ.",
"Passwords do not match": "ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಹೊಂದುತ್ತಿಲ್ಲ",
