"Good evening": "ಶುಭ ಸಂಜೆ",
"All clear for today, {name}. {done} done. You earned a breather.": "ಇಂದಿನ ಕೆಲಸ ಎಲ್ಲಾ ಮುಗಿದಿದೆ, {name}. {done} ಮುಗಿದಿವೆ. ಸ್ವಲ್ಪ ವಿಶ್ರಾಂತಿ ಪಡೆಯಿರಿ.",
"Everything on today's list is finished, {name}. That's a good day's work.": "ಇಂದಿನ ಪಟ್ಟಿಯ ಎಲ್ಲವೂ ಮುಗಿದಿದೆ, {name}. ಒಳ್ಳೆಯ ದಿನದ ಕೆಲಸ ಇದು.",
"{streak} days in a row, {name}. That's not luck, that's who you're becoming.": "ಸತತ {streak} ದಿನ, {name}. ಇದು ಅದೃಷ್ಟವಲ್ಲ, ನೀವು ಆಗುತ್ತಿರುವ ವ್ಯಕ್ತಿ ಇದು.",
"{streak}-day streak, {name}! You're building something real.": "{streak} ದಿನಗಳ ಸ್ಟ್ರೀಕ್, {name}! ನೀವು ಏನೋ ನಿಜವಾದದ್ದನ್ನು ಕಟ್ಟುತ್ತಿದ್ದೀರಿ.",
"Day {streak} of your streak, {name}. Keep the chain going.": "ನಿಮ್ಮ ಸ್ಟ್ರೀಕ್‌ನ {streak}ನೇ ದಿನ, {name}. ಸರಪಳಿ ಮುಂದುವರಿಸಿ.",
"{streak} days straight, {name}. Nice rhythm.": "ಸತತ {streak} ದಿನ, {name}. ಒಳ್ಳೆಯ ಲಯ.",
"Your {streak}-day streak is waiting on you, {name}. One tick keeps it alive.": "ನಿಮ್ಮ {streak} ದಿನಗಳ ಸ್ಟ್ರೀಕ್ ನಿಮಗಾಗಿ ಕಾಯುತ್ತಿದೆ, {name}. ಒಂದು ಟಿಕ್ ಮಾಡಿದರೆ ಅದು ಉಳಿಯುತ್ತದೆ.",
"Finish one thing today, {name}, and your {streak}-day streak lives on.": "ಇಂದು ಒಂದು ಕೆಲಸ ಮುಗಿಸಿ, {name}, ನಿಮ್ಮ {streak} ದಿನಗಳ ಸ್ಟ್ರೀಕ್ ಮುಂದುವರಿಯುತ್ತದೆ.",
"A few things slipped, {name}. That's okay: pick the smallest one and start there.": "ಕೆಲವು ಕೆಲಸಗಳು ಬಿಟ್ಟುಹೋದವು, {name}. ಪರವಾಗಿಲ್ಲ: ಅತಿ ಚಿಕ್ಕದನ್ನು ಆರಿಸಿ ಅಲ್ಲಿಂದ ಶುರು ಮಾಡಿ.",
"Some reminders are behind, {name}. One at a time, starting with the easiest.": "ಕೆಲವು ರಿಮೈಂಡರ್‌ಗಳು ಹಿಂದೆ ಉಳಿದಿವೆ, {name}. ಸುಲಭವಾದದ್ದರಿಂದ ಶುರು ಮಾಡಿ, ಒಂದೊಂದಾಗಿ.",
"{done} down today, {name}. {pending} to go.": "ಇಂದು {done} ಮುಗಿದಿವೆ, {name}. {pending} ಬಾಕಿ.",
"{done} done, {pending} left, {name}. Keep the momentum.": "{done} ಮುಗಿದಿವೆ, {pending} ಉಳಿದಿವೆ, {name}. ಇದೇ ವೇಗ ಮುಂದುವರಿಸಿ.",
"Your best run was {best} days, {name}. Today is a good day to beat it.": "ನಿಮ್ಮ ಅತ್ಯುತ್ತಮ ಓಟ {best} ದಿನ, {name}. ಇಂದು ಅದನ್ನು ಮೀರಿಸಲು ಒಳ್ಳೆಯ ದಿನ.",
"A fresh start, {name}. Your best streak is {best} days; let's go past it.": "ಹೊಸ ಆರಂಭ, {name}. ನಿಮ್ಮ ಅತ್ಯುತ್ತಮ ಸ್ಟ್ರೀಕ್ {best} ದಿನ; ಅದನ್ನು ದಾಟೋಣ.",
"A free day, {name}. Plan one thing you'd be proud of tonight.": "ಖಾಲಿ ದಿನ, {name}. ಇಂದು ರಾತ್ರಿ ಹೆಮ್ಮೆ ಪಡುವಂಥ ಒಂದು ಕೆಲಸ ಯೋಜಿಸಿ.",
"Nothing due today, {name}. A good moment to get ahead.": "ಇಂದು ಏನೂ ಬಾಕಿ ಇಲ್ಲ, {name}. ಮುಂದೆ ಹೋಗಲು ಒಳ್ಳೆಯ ಸಮಯ.",
"You've got this, {name}.": "ನಿಮ್ಮಿಂದ ಆಗುತ್ತದೆ, {name}.",
"One thing at a time, {name}.": "ಒಂದು ಬಾರಿಗೆ ಒಂದು ಕೆಲಸ, {name}.",
"Checking status…": "ಸ್ಥಿತಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತಿದೆ…",
"Connecting…": "ಕನೆಕ್ಟ್ ಆಗುತ್ತಿದೆ…",
"Systems Operational": "ಎಲ್ಲಾ ಸಿಸ್ಟಮ್ ಕೆಲಸ ಮಾಡುತ್ತಿವೆ",
"Connection issue": "ಕನೆಕ್ಷನ್ ಸಮಸ್ಯೆ",
"Type or speak “DBMS assignment tomorrow 5pm” or “gym every Monday at 7am” and AI fills in the title, schedule and category for you.": "“ನಾಳೆ ಸಂಜೆ 5pm DBMS ಅಸೈನ್‌ಮೆಂಟ್” ಅಥವಾ “ಪ್ರತಿ ಸೋಮವಾರ 7am ಜಿಮ್” ಎಂದು ಟೈಪ್ ಮಾಡಿ ಅಥವಾ ಹೇಳಿ; ಶೀರ್ಷಿಕೆ, ವೇಳಾಪಟ್ಟಿ ಮತ್ತು ವರ್ಗವನ್ನು AI ತುಂಬುತ್ತದೆ.",
"Specific, Daily & Weekly Reminders": "ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್‌ಗಳು",
"Set one-time deadlines or repeat reminders every day or on chosen weekdays, delivered through browser Web Push and Telegram.": "ಒಮ್ಮೆಯ ಡೆಡ್‌ಲೈನ್ ಇಡಿ, ಅಥವಾ ಪ್ರತಿದಿನ ಅಥವಾ ಆರಿಸಿದ ವಾರದ ದಿನಗಳಲ್ಲಿ ರಿಮೈಂಡರ್ ಪುನರಾವರ್ತಿಸಿ; ಬ್ರೌಸರ್ ವೆಬ್ ಪುಶ್ ಮತ್ತು ಟೆಲಿಗ್ರಾಮ್ ಮೂಲಕ ಬರುತ್ತವೆ.",
"Private by Design": "ವಿನ್ಯಾಸದಲ್ಲೇ ಖಾಸಗಿ",
"Your reminder titles, notes and categories are encrypted before they are stored, and inappropriate content is screened out automatically.": "ನಿಮ್ಮ ರಿಮೈಂಡರ್ ಶೀರ್ಷಿಕೆ, ಟಿಪ್ಪಣಿ ಮತ್ತು ವರ್ಗಗಳನ್ನು ಉಳಿಸುವ ಮೊದಲು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗುತ್ತದೆ, ಮತ್ತು ಅನುಚಿತ ವಿಷಯವನ್ನು ತಾನಾಗಿ ಫಿಲ್ಟರ್ ಮಾಡಲಾಗುತ್ತದೆ.",
"Installable Web App": "ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಬಹುದಾದ ವೆಬ್ ಆ್ಯಪ್",
"Add GetRemindMe to your home screen and use it like a native app on your phone or laptop, synced across devices.": "GetRemindMe ಅನ್ನು ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಸೇರಿಸಿ, ಫೋನ್ ಅಥವಾ ಲ್ಯಾಪ್‌ಟಾಪ್‌ನಲ್ಲಿ ನೇಟಿವ್ ಆ್ಯಪ್‌ನಂತೆ ಬಳಸಿ; ಎಲ್ಲಾ ಸಾಧನಗಳಲ್ಲಿ ಸಿಂಕ್ ಆಗುತ್ತದೆ.",
"Create Task": "ಟಾಸ್ಕ್ ರಚಿಸಿ",
"See Updates": "ಅಪ್‌ಡೇಟ್‌ಗಳನ್ನು ನೋಡಿ",
"Help & FAQs": "ಸಹಾಯ ಮತ್ತು FAQ",
