"Call mom tomorrow morning": "ನಾಳೆ ಬೆಳಿಗ್ಗೆ ಅಮ್ಮನಿಗೆ ಕರೆ ಮಾಡಿ",
"Pay rent on the 1st": "1ನೇ ತಾರೀಖಿಗೆ ಬಾಡಿಗೆ ಕಟ್ಟಿ",
