"Get a pop-up on this device when a reminder is due, even when GetRemindMe isn't open. This is set per device, so turn it on for each phone or computer you use.": "ರಿಮೈಂಡರ್ ಸಮಯ ಬಂದಾಗ, GetRemindMe ತೆರೆದಿಲ್ಲದಿದ್ದರೂ ಈ ಸಾಧನದಲ್ಲಿ ಪಾಪ್-ಅಪ್ ಪಡೆಯಿರಿ. ಇದು ಪ್ರತಿ ಸಾಧನಕ್ಕೆ ಪ್ರತ್ಯೇಕ, ಹಾಗಾಗಿ ನೀವು ಬಳಸುವ ಪ್ರತಿ ಫೋನ್ ಅಥವಾ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಆನ್ ಮಾಡಿ.",
"This browser can't receive push alerts. On iPhone or iPad, add GetRemindMe to your Home Screen first, then open it from there.": "ಈ ಬ್ರೌಸರ್ ಪುಶ್ ಅಲರ್ಟ್ ಸ್ವೀಕರಿಸಲಾಗದು. iPhone ಅಥವಾ iPad ನಲ್ಲಿ ಮೊದಲು GetRemindMe ಅನ್ನು ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಸೇರಿಸಿ, ನಂತರ ಅಲ್ಲಿಂದ ತೆರೆಯಿರಿ.",
"Notifications are blocked for this site. Allow them from the lock icon next to the address bar (or your browser's site settings), then come back and turn alerts on.": "ಈ ಸೈಟ್‌ಗೆ ನೋಟಿಫಿಕೇಶನ್ ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ. ವಿಳಾಸ ಪಟ್ಟಿಯ ಪಕ್ಕದ ಲಾಕ್ ಐಕಾನ್‌ನಿಂದ (ಅಥವಾ ಬ್ರೌಸರ್‌ನ ಸೈಟ್ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಿಂದ) ಅನುಮತಿಸಿ, ನಂತರ ಹಿಂದಿರುಗಿ ಅಲರ್ಟ್ ಆನ್ ಮಾಡಿ.",
