"New features and release notes will show up here as soon as they're published.": "ಹೊಸ ವೈಶಿಷ್ಟ್ಯಗಳು ಮತ್ತು ರಿಲೀಸ್ ನೋಟ್ಸ್ ಪ್ರಕಟವಾದ ಕೂಡಲೇ ಇಲ್ಲಿ ಕಾಣುತ್ತವೆ.",
"Tap Download app. Your browser may say the file \"can harm your device\": tap Download anyway. It is the normal warning for apps outside the Play Store.": "ಡೌನ್‌ಲೋಡ್ ಆ್ಯಪ್ ಟ್ಯಾಪ್ ಮಾಡಿ. ಫೈಲ್ “ನಿಮ್ಮ ಸಾಧನಕ್ಕೆ ಹಾನಿ ಮಾಡಬಹುದು” ಎಂದು ಬ್ರೌಸರ್ ಹೇಳಬಹುದು: ಆದರೂ ಡೌನ್‌ಲೋಡ್ ಟ್ಯಾಪ್ ಮಾಡಿ. ಪ್ಲೇ ಸ್ಟೋರ್ ಹೊರಗಿನ ಆ್ಯಪ್‌ಗಳಿಗೆ ಇದು ಸಾಮಾನ್ಯ ಎಚ್ಚರಿಕೆ.",
"Open the downloaded GetRemindMe.apk from the notification or your Downloads folder.": "ಡೌನ್‌ಲೋಡ್ ಆದ GetRemindMe.apk ಅನ್ನು ನೋಟಿಫಿಕೇಶನ್ ಅಥವಾ ಡೌನ್‌ಲೋಡ್ಸ್ ಫೋಲ್ಡರ್‌ನಿಂದ ತೆರೆಯಿರಿ.",
"If Android asks, tap Settings, switch on Allow from this source, then go back and tap Install.": "Android ಕೇಳಿದರೆ, ಸೆಟ್ಟಿಂಗ್ಸ್ ಟ್ಯಾಪ್ ಮಾಡಿ, “ಈ ಮೂಲದಿಂದ ಅನುಮತಿಸಿ” ಆನ್ ಮಾಡಿ, ಹಿಂದೆ ಬಂದು ಇನ್‌ಸ್ಟಾಲ್ ಟ್ಯಾಪ್ ಮಾಡಿ.",
"Open GetRemindMe, log in with the same account, and allow notifications so your reminders can ring.": "GetRemindMe ತೆರೆಯಿರಿ, ಅದೇ ಖಾತೆಯಿಂದ ಲಾಗ್ ಇನ್ ಮಾಡಿ, ಮತ್ತು ರಿಮೈಂಡರ್‌ಗಳು ರಿಂಗ್ ಆಗಲು ನೋಟಿಫಿಕೇಶನ್ ಅನುಮತಿಸಿ.",
"For alarms that never get late: allow exact alarms and set the app's battery use to Unrestricted.": "ತಡವಾಗದ ಅಲಾರಂಗಳಿಗೆ: ನಿಖರ ಅಲಾರಂ ಅನುಮತಿಸಿ ಮತ್ತು ಆ್ಯಪ್‌ನ ಬ್ಯಾಟರಿ ಬಳಕೆಯನ್ನು ಅನಿರ್ಬಂಧಿತ ಮಾಡಿ.",
