"Are you absolutely sure?": "ನೀವು ಖಂಡಿತ ಖಚಿತವೇ?",
"This permanently deletes your account, reminders and profile picture. It cannot be undone.": "ಇದು ನಿಮ್ಮ ಖಾತೆ, ರಿಮೈಂಡರ್‌ಗಳು ಮತ್ತು ಪ್ರೊಫೈಲ್ ಚಿತ್ರವನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸುತ್ತದೆ. ಇದನ್ನು ರದ್ದುಮಾಡಲಾಗದು.",
