"Delete My Data": "ನನ್ನ ಡೇಟಾ ಅಳಿಸಿ",
"GetRemindMe: specific, daily and weekly reminders": "GetRemindMe: ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್‌ಗಳು",
"GetRemindMe: Specific, Daily & Weekly Reminders": "GetRemindMe: ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್‌ಗಳು",
"GetRemindMe sends specific, daily and weekly reminders to Telegram and your browser. Type or speak a task, try it free without signing up, and never miss a deadline or habit again.": "GetRemindMe ಟೆಲಿಗ್ರಾಮ್ ಮತ್ತು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ಗೆ ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್ ಕಳುಹಿಸುತ್ತದೆ. ಕೆಲಸವನ್ನು ಟೈಪ್ ಮಾಡಿ ಅಥವಾ ಹೇಳಿ, ಸೈನ್ ಅಪ್ ಮಾಡದೆ ಉಚಿತವಾಗಿ ಪ್ರಯತ್ನಿಸಿ, ಇನ್ನೆಂದೂ ಡೆಡ್‌ಲೈನ್ ಅಥವಾ ಅಭ್ಯಾಸ ತಪ್ಪಿಸಿಕೊಳ್ಳಬೇಡಿ.",
"About GetRemindMe: a reminder app for specific, daily and weekly reminders with Magic Add AI, Telegram and browser notifications, and encrypted private reminders.": "GetRemindMe ಬಗ್ಗೆ: Magic Add AI, ಟೆಲಿಗ್ರಾಮ್ ಮತ್ತು ಬ್ರೌಸರ್ ನೋಟಿಫಿಕೇಶನ್, ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆದ ಖಾಸಗಿ ರಿಮೈಂಡರ್‌ಗಳೊಂದಿಗೆ ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್ ಆ್ಯಪ್.",
"FAQs & Help": "FAQ ಮತ್ತು ಸಹಾಯ",
"Answers about GetRemindMe: daily, weekly and one-time reminders, Magic Add, Telegram and browser notifications, privacy and your account.": "GetRemindMe ಬಗ್ಗೆ ಉತ್ತರಗಳು: ದೈನಂದಿನ, ಸಾಪ್ತಾಹಿಕ ಮತ್ತು ಒಮ್ಮೆಯ ರಿಮೈಂಡರ್, Magic Add, ಟೆಲಿಗ್ರಾಮ್ ಮತ್ತು ಬ್ರೌಸರ್ ನೋಟಿಫಿಕೇಶನ್, ಗೌಪ್ಯತೆ ಮತ್ತು ನಿಮ್ಮ ಖಾತೆ.",
"Terms of Service & Privacy Policy": "ಸೇವಾ ನಿಯಮಗಳು ಮತ್ತು ಗೌಪ್ಯತಾ ನೀತಿ",
"Read the GetRemindMe Terms of Service and Privacy Policy: how your reminders are encrypted, which notification channels we use, and how to delete your data.": "GetRemindMe ಸೇವಾ ನಿಯಮಗಳು ಮತ್ತು ಗೌಪ್ಯತಾ ನೀತಿ ಓದಿ: ನಿಮ್ಮ ರಿಮೈಂಡರ್‌ಗಳು ಹೇಗೆ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗುತ್ತವೆ, ಯಾವ ನೋಟಿಫಿಕೇಶನ್ ಚಾನೆಲ್‌ಗಳನ್ನು ಬಳಸುತ್ತೇವೆ, ಮತ್ತು ನಿಮ್ಮ ಡೇಟಾ ಅಳಿಸುವುದು ಹೇಗೆ.",
"Log in to GetRemindMe to see your reminders and manage daily, weekly and one-time alerts.": "ನಿಮ್ಮ ರಿಮೈಂಡರ್‌ಗಳನ್ನು ನೋಡಲು ಮತ್ತು ದೈನಂದಿನ, ಸಾಪ್ತಾಹಿಕ ಹಾಗೂ ಒಮ್ಮೆಯ ಅಲರ್ಟ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಲು GetRemindMe ಗೆ ಲಾಗ್ ಇನ್ ಮಾಡಿ.",
"Create your free account": "ನಿಮ್ಮ ಉಚಿತ ಖಾತೆ ರಚಿಸಿ",
"Sign up for GetRemindMe free and get specific, daily and weekly reminders on Telegram and in your browser.": "GetRemindMe ಗೆ ಉಚಿತವಾಗಿ ಸೈನ್ ಅಪ್ ಮಾಡಿ ಮತ್ತು ಟೆಲಿಗ್ರಾಮ್ ಹಾಗೂ ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ನಿರ್ದಿಷ್ಟ, ದೈನಂದಿನ ಮತ್ತು ಸಾಪ್ತಾಹಿಕ ರಿಮೈಂಡರ್ ಪಡೆಯಿರಿ.",
