"Could not make the streak card. Please try again.": "ಸ್ಟ್ರೀಕ್ ಕಾರ್ಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
"Your name": "ನಿಮ್ಮ ಹೆಸರು",
