"Connector": "ಕನೆಕ್ಟರ್",
"Share my streak": "ನನ್ನ ಸ್ಟ್ರೀಕ್ ಹಂಚಿ",
"Quick add": "ಕ್ವಿಕ್ ಆ್ಯಡ್",
"Forget what quick add learned": "ಕ್ವಿಕ್ ಆ್ಯಡ್ ಕಲಿತದ್ದನ್ನು ಮರೆಸಿ",
"It learns on this device only which category you pick. Your reminders stay as they are.": "ನೀವು ಯಾವ ವರ್ಗ ಆರಿಸುತ್ತೀರಿ ಎಂಬುದನ್ನು ಇದು ಈ ಸಾಧನದಲ್ಲಿ ಮಾತ್ರ ಕಲಿಯುತ್ತದೆ. ನಿಮ್ಮ ಜ್ಞಾಪನೆಗಳು ಹಾಗೆಯೇ ಇರುತ್ತವೆ.",
"Quick add has forgotten your category choices.": "ಕ್ವಿಕ್ ಆ್ಯಡ್ ನಿಮ್ಮ ವರ್ಗದ ಆಯ್ಕೆಗಳನ್ನು ಮರೆತಿದೆ.",
